"use client";
import React, { useState } from "react";

const CheckoutPage = () => {
  const [shippingMethod, setShippingMethod] = useState("address");
  const [paymentMethod, setPaymentMethod] = useState("card");
  const [cardInfo, setCardInfo] = useState({
    cardNumber: "",
    name: "",
    expDate: "",
    cvv: "",
  });

  const shippingCost = shippingMethod === "address" ? 5 : 0;
  const paymentCost = paymentMethod === "cash" ? 1 : 0;
  const finalAmount = shippingCost + paymentCost;

  const handleCardChange = (e: { target: { name: any; value: any; }; }) => {
    const { name, value } = e.target;
    setCardInfo({ ...cardInfo, [name]: value });
  };

  const handleConfirm = () => {
    alert(`Order confirmed! Total: ${finalAmount}€`);
  };

  return (
    <div style={{ fontFamily: "Arial, sans-serif", backgroundColor: "#e6f0fa", minHeight: "100vh", padding: "2rem" }}>
      <div style={{ maxWidth: "800px", margin: "0 auto" }}>
        <h1 style={{ textAlign: "center", marginBottom: "2rem" }}>Επίλεξε τον τρόπο αποστολής και πληρωμής</h1>
        
        {/* Shipping Method */}
        <div style={{ backgroundColor: "white", borderRadius: "8px", padding: "1.5rem", marginBottom: "2rem", boxShadow: "0 2px 5px rgba(0,0,0,0.1)" }}>
          <h2>Shipping method</h2>
          <div>
            <label>
              <input
                type="radio"
                name="shipping"
                value="address"
                checked={shippingMethod === "address"}
                onChange={() => setShippingMethod("address")}
              /> Address
            </label>
          </div>
          <div>
            <label>
              <input
                type="radio"
                name="shipping"
                value="boxNow"
                checked={shippingMethod === "boxNow"}
                onChange={() => setShippingMethod("boxNow")}
              /> BOX NOW
            </label>
          </div>
        </div>

        {/* Payment Method */}
        <div style={{ backgroundColor: "white", borderRadius: "8px", padding: "1.5rem", marginBottom: "2rem", boxShadow: "0 2px 5px rgba(0,0,0,0.1)" }}>
          <h2>Payment method</h2>
          <div>
            <label>
              <input
                type="radio"
                name="payment"
                value="cash"
                checked={paymentMethod === "cash"}
                onChange={() => setPaymentMethod("cash")}
              /> Cash on delivery (+1,00€)
            </label>
          </div>
          <div>
            <label>
              <input
                type="radio"
                name="payment"
                value="card"
                checked={paymentMethod === "card"}
                onChange={() => setPaymentMethod("card")}
              /> Card
            </label>
          </div>

          {paymentMethod === "card" && (
            <div style={{ marginTop: "1rem" }}>
              <div>
                <label>Card number</label>
                <input type="text" name="cardNumber" placeholder="card number" value={cardInfo.cardNumber} onChange={handleCardChange} />
              </div>
              <div>
                <label>Name on card</label>
                <input type="text" name="name" placeholder="name" value={cardInfo.name} onChange={handleCardChange} />
              </div>
              <div>
                <label>Expiration date</label>
                <input type="text" name="expDate" placeholder="exp. date" value={cardInfo.expDate} onChange={handleCardChange} />
              </div>
              <div>
                <label>CVV</label>
                <input type="text" name="cvv" placeholder="CVV" value={cardInfo.cvv} onChange={handleCardChange} />
              </div>
            </div>
          )}
        </div>

        {/* Final Amount */}
        <div style={{ float: "right", backgroundColor: "white", borderRadius: "8px", padding: "1rem", width: "200px", textAlign: "center", boxShadow: "0 2px 5px rgba(0,0,0,0.1)" }}>
          <h3>Final amount</h3>
          <p>Delivery: {shippingCost.toFixed(2)}€</p>
          <p>+ {paymentCost.toFixed(2)}€</p>
          <hr />
          <p>{finalAmount.toFixed(2)}€</p>
          <button onClick={handleConfirm} style={{ backgroundColor: "#0b1d59", color: "white", padding: "0.5rem 1rem", border: "none", borderRadius: "4px", cursor: "pointer" }}>Confirm</button>
        </div>
      </div>
    </div>
  );
};

export default CheckoutPage;
